/*
    Analytically Box-Filtered Grid by chronos
    ------------------------------------------------------------------------------

    mouse.x = filter size
    mouse.y = grid line thickness

    ------------------------------------------------------------------------------

    Analytically box-filtered grid, but this one should be exact (if I haven't made a mistake somewhere! 😄).
    unlike some other approximate grid AA methods I've seen, this one also handles the case where the
    filter kernel is larger (even much larger) than the grid cell size, as well as the undulation
    from phase offsets.

    The grid is created by adding together analytically box filtered
    horizontal and vertical pulse-waves with adjustable duty cycles.
    Note that doing only this would give the wrong result in the corners,
    because of double counting where the lines overlap.

    This method also corrects the corners by making use of the fact that
    the box filter being separable. We simply multiply the horizontal and vertical results
    to recreate the corners and subtracted them from the sum 
    in order to compensate forthe double-counting.

    Note that this method is not enough to get perfectly anti-aliased grids in 3D,
    for that you would need to convolve with the anisotropic pixel-footprint
    due to the perspective and camera angle, which is more complicated.
    If you can approximate that though, then you can probably use this method
    by matching the area of the pixel footprint with the kernel-area in this shader.

    There is one know issue currently, and that is that there's sometimes an edge case where a single value
    is not correct. This is likely due to me using the ceil fuction somehow 😄
    Let me know if you figure out how to correct that little bug or spot any other!

    ( I thought I had made a shader like this before, but now I can't find it, so had to make this, heh ^_^ )

    ------------------------------------------------------------------------------

    self link: https://www.shadertoy.com/view/XXGyWV

    ------------------------------------------------------------------------------


*/

float pulse_wave_box_filtered_inlined(float duty, float filterwidth, float x)
{
    float a = x-filterwidth/2.;
    float b = x+filterwidth/2.;
    float start_cell = floor(a);
    float end_cell   = floor(b);
    float result = 0.;
    {
        // Count whole cells
        result += (end_cell - min(ceil(a), end_cell)) * duty; 

        // Count start and end intervals
        result += clamp(duty + start_cell-a, 0., filterwidth);
        result += start_cell == end_cell ? 0. : max(min(b - end_cell, duty) - clamp(a - end_cell, 0., duty), 0.);
    }
    return result / filterwidth;
}

float box(vec2 p, float width) // Just used to draw the kernel shape in the middle
{
    float halfwidth = width/2.;
    p = abs(p) - halfwidth;
    return min(p.x, p.y) > 1. ? length(p) : max(p.x, p.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float zoom   = 2.;
    vec2 uv      = zoom * (2. * fragCoord - iResolution.xy) / iResolution.y;
    vec2 mouse1  = zoom * (2. * abs(iMouse.xy) - iResolution.xy) / iResolution.y;
    vec2 mouse0  = zoom * (2. * abs(iMouse.zw) - iResolution.xy) / iResolution.y;
    float ps     = zoom *  2. / iResolution.y;

    const float PI  = 3.14159265;
    if(length(iMouse.xy) < 10.) mouse1 = vec2(1.66*sin(PI * fract(iTime*.1)) * sin(PI*fract(iTime * 0.01)), .25);

    vec3 color = vec3(0);

    #if 0
        float filterwidth = 1.;
    #else
        float filterwidth = 1.2  * mouse1.x;
    #endif

    float grid_thickness = 0.50 * abs(mouse1.y);
    grid_thickness = clamp(grid_thickness, 0., 1.);


    // This creates the actual filtered grid!
    float grid = 
        pulse_wave_box_filtered_inlined(grid_thickness, filterwidth, uv.x)
        +
        pulse_wave_box_filtered_inlined(grid_thickness, filterwidth, uv.y)
        -
        pulse_wave_box_filtered_inlined(grid_thickness, filterwidth, uv.x)
        *
        pulse_wave_box_filtered_inlined(grid_thickness, filterwidth, uv.y)
    ;

    if(uv.x < .0)
    {
        /*
        color = mix(color, vec3(0.7, 0.0, 0.3), 0.01 + 0.99 * .1);
        color = mix(color, vec3(0.0, 0.3, 0.7), 0.01 + 0.99 * f);
        */
        color += mix(vec3(0.4, 0.2+0.6*(uv.y*.5+.5), 0.9), vec3(0.8, 0.2, 0.1), grid);
        color *= 1.-0.125*length(uv);
    }
    else
        color += grid;

    color = mix(color, vec3(1), smoothstep(ps, -ps, box(uv, filterwidth)) / filterwidth);
    color = mix(color, vec3(0), .5*smoothstep(ps, -ps, abs(box(uv, filterwidth))-0.01) / filterwidth);

    fragColor = vec4(pow(color, vec3(1./2.2)), 1);
}
